mapper.select:
select distinct sbmci.SEQ_NO seqNo, sbmci.BROKER_ID brokerId, /*券商代码*/ mci.CUSTOMER_NAME brokerName, /*券商名称*/ sbmci.ACCT_NO accountType, R.ACCT_NAME accountTypeStr, sbmci.FINPROD_ID finprodId, /*资产代码*/ fin.FINPROD_MARKET_ID finprodMarketId, fin.FINPROD_ABBR finprodAbbr, /*资产名称*/ sbmci.MORE_CONVRATE * 100 moreConvrate,/*标准券折算率%*/ sbmci.START_DATE startDate,/*开始日期*/ sbmci.END_DATE endDate/*结束日期*/ from STD_BOND_MORE_CONVRATE_INFO sbmci left join MST_CUSTOMER_INFO mci on sbmci.BROKER_ID = mci.CUSTOMER_ID left join FIN_PRODUCT fin on sbmci.FINPROD_ID = fin.FINPROD_ID left join PTL_CAPACCT_INFO t on sbmci.ACCT_NO = t.ACCT_NO LEFT JOIN STL_CAPACCT_INFO R ON T.ACCT_NO = R.ACCT_NO AND T.CCY = R.CCY
sbmci.BROKER_ID = #{brokerId,jdbcType=VARCHAR}
AND sbmci.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND sbmci.ACCT_NO = #{accountType,jdbcType=VARCHAR}

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

select sbmci.SEQ_NO seqNo, sbmci.BROKER_ID brokerId, sbmci.ACCT_NO accountType, sbmci.FINPROD_ID finprodId, sbmci.START_DATE startDate, sbmci.MORE_CONVRATE * 100 moreConvrate, sbmci.START_DATE startDate,/*开始日期*/ sbmci.END_DATE endDate/*结束日期*/ from STD_BOND_MORE_CONVRATE_INFO sbmci where sbmci.BROKER_ID = #{brokerId,jdbcType=VARCHAR}
AND sbmci.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND sbmci.ACCT_NO = #{accountType,jdbcType=VARCHAR}
and sbmci.START_DATE = #{startDate,jdbcType=VARCHAR}

