and sbmci.ACCT_NO =  #{accountType,jdbcType=VARCHAR}

mapper.select:
select pci.ACCT_NO id , sci.ACCT_NAME text from STL_CAPACCT_INFO sci LEFT JOIN PTL_CAPACCT_INFO pci ON pci.ACCT_NO = sci.ACCT_NO AND pci.CCY = sci.CCY LEFT JOIN(select msd.SALE_DEPID SALE_DEPID,mci.CUSTOMER_ID from mst_sale_department msd left join mst_customer_info mci on mci.CUSTOMER_ID = msd.BROKER_ID where mci.IS_BROKER = 'Y' ) T on T.SALE_DEPID = sci.OWN_DEPT
pci.ACCT_TYPE = 'A07'
and T.CUSTOMER_ID = #{broker,jdbcType=VARCHAR}

select FINPROD_ID
from FIN_PRODUCT
where FINPROD_TYPE2 = #{F01_TG}
and FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
AND TRADE_MARKET IN (#{TRADE_PLACE_03},#{TRADE_PLACE_04})
AND ROWNUM = 1
